 auto created=data;created["asset"]=AssetId::random().text();auto fresh=assets.create_native("new.daeffect",created.dump());check(fresh.root.text()==created["asset"].get<std::string>()&&fresh.changed,"Native creation validates a fresh identity");rejects([&]{assets.create_native("new.daeffect",created.dump());});rejects([&]{assets.create_native("duplicate.daeffect",created.dump());});created["asset"]=AssetId::random().text();created["duration_ticks"]=0;rejects([&]{assets.create_native("invalid.daeffect",created.dump());});check(!std::filesystem::exists(sources/"invalid.daeffect"),"Invalid creation rolls back owned source and inventory");rejects([&]{assets.create_native("../escape.daeffect",created.dump());});
