 set[0].expected_sha256=sha256(valid.dump());set[1].expected_sha256=sha256(invalid_second.dump());auto warm=assets.prepare_native(set);for(auto result:assets.commit_native(warm))check(!result.changed,"Unchanged coordinated cook keeps generation");
 auto stale=assets.prepare_native(set);auto external_edit=valid;external_edit["duration_ticks"]=126;std::ofstream(sources/"burn.daeffect",std::ios::binary)<<external_edit.dump();rejects([&]{assets.commit_native(stale);});check(read(sources/"burn.daeffect")==external_edit.dump(),"Prepared stale writer preserves external changes");
 std::ofstream(sources/"external.glb")<<"external-original";rejects([&]{assets.edit_native("external.glb",sha256("external-original"),edited);});check(read(sources/"external.glb")=="external-original","External interchange files cannot enter native edit path");
